const { Expression } = require('../core/expression');
const { FunctionNode, OperatorNode } = require('mathjs');

const infixOperators = {
  add: '+',
  subtract: '-',
  multiply: '*',
  divide: '/'
};

function convertInfixFunctions(node) {
  let converted = node.map((child) => convertInfixFunctions(child));
  if (converted.type !== 'FunctionNode') return converted;

  let { name } = converted.fn;
  if (Object.prototype.hasOwnProperty.call(infixOperators, name)) {
    return new OperatorNode(infixOperators[name], name, converted.args);
  }
  if (name === 'logbase') {
    let args = converted.args;
    return new OperatorNode('/', 'divide', [new FunctionNode('log', [args[0]]), new FunctionNode('log', [args[1]])]);
  }
  return converted;
}

Expression.prototype.toCString = function(logger, _mathOptions = {}, substituteByDefinitions = true){
  // set defaults
  let mathOptions = Object.assign({
    timeVariable: 'TIME' // default time variable name, can be overridden by options
  }, _mathOptions);

  let tree = substituteByDefinitions ? this.substituteByDefinitions().exprParsed : this.exprParsed;
  tree = convertInfixFunctions(tree);

  let CStringHandler = (node, options) => {
    // ConstantNode
    if (node.type === 'ConstantNode' && Number.isInteger(node.value)) {
      return node.value + '.0';
    }

    // OperatorNode
    if (node.type === 'OperatorNode') {
      if (node.fn === 'and') {
        return node.args
          .map((arg) => arg.toString(options))
          .join(' && ');
      }
      if (node.fn === 'or') {
        return node.args
          .map((arg) => arg.toString(options))
          .join(' || ');
      }
      if (node.fn === 'xor') {
        let args = node.args
          .map((arg) => arg.toString(options))
          .join(', ');
        return `xor(${args})`;
      }
      if (node.fn === 'not') {
        let arg0 = node.args[0].toString(options, true);
        return `!${arg0}`;
      }
      if (node.fn === 'pow') {
        return `pow(${node.args[0].toString(options)}, ${node.args[1].toString(options)})`;
      }
      if (node.fn === 'unaryPlus') {
        return node.args[0].toString(options);
      }
    }

    // FunctionNode
    if (node.type === 'FunctionNode') {
      if (node.fn.name === 'abs') {
        return `fabs(${node.args[0].toString(options)})`;
      }
      if (node.fn.name === 'max') {
        let args = node.args
          .map((arg) => arg.toString(options))
          .join(', ');
        return `std::max(${args})`;
      }
      if (node.fn.name === 'min') {
        let args = node.args
          .map((arg) => arg.toString(options))
          .join(', ');
        return `std::min(${args})`;
      }
      if (node.fn.name === 'factorial') {
        return `tgamma(${node.args[0].toString(options)} + 1.0)`;
      }
      if (node.fn.name === 'piecewise') {
        let msg = `mrgsolve format does not support "piecewise" function, got "${node.toString()}"`;
        logger && logger.error(msg);
        let args = node.args
          .map((arg) => arg.toString(options));
        return `piecewise(${args.join(',')})`;
      }
    }

    // SymbolNode
    if (node.type === 'SymbolNode' && node.name === 't') {
      return mathOptions.timeVariable;
    }
  };

  return tree.toString({
    parenthesis: 'keep',
    implicit: 'show',   
    handler: CStringHandler
  });
};
